38	import static org.apache.camel.processor.PipelineHelper.continueProcessing;
39	
40	/**
41	 * Implements a Choice structure where one or more predicates are used which if they are true their processors are used,
42	 * with a default otherwise clause used if none match.
43	 */
44	public class ChoiceProcessor extends BaseProcessorSupport
45	        implements Navigate<Processor>, Traceable, IdAware, RouteIdAware, StepIdAware {
46	
47	    private static final Logger LOG = LoggerFactory.getLogger(ChoiceProcessor.class);
48	
49	    private String id;
50	    private String routeId;
51	    private String stepId;
52	    // optimize to use an array
53	    private final FilterProcessor[] filters;
54	    private final int len;
55	    private final AsyncProcessor otherwise;
56	    private transient long notFiltered;
57	
58	    public ChoiceProcessor(List<FilterProcessor> filters, Processor otherwise) {
59	        this.filters = filters.toArray(new FilterProcessor[0]);
60	        this.len = filters.size();
61	        this.otherwise = otherwise != null ? AsyncProcessorConverterHelper.convert(otherwise) : null;
62	    }
63	
64	    @Override
65	    public boolean process(final Exchange exchange, final AsyncCallback callback) {
66	        // find the first matching filter and process the exchange using it
67	        for (int i = 0; i < len; i++) {
68	            FilterProcessor filter = filters[i];
69	            // evaluate the predicate on filter predicate early to be faster
70	            // and avoid issues when having nested choices
71	            // as we should only pick one processor
72	            boolean matches = false;
73	            try {
74	                matches = filter.matches(exchange);
75	            } catch (Exception e) {
76	                exchange.setException(e);
77	            }
78	
79	            // check for error if so we should break out
80	            if (!continueProcessing(exchange, "so breaking out of choice", LOG)) {
81	                // okay there was an error in the predicate so we should exit
82	                callback.done(true);
83	                return true;
84	            }
85	
86	            // if we did not match then continue to next filter
87	            if (!matches) {
88	                // prepare for re-read from next filter
89	                MessageHelper.resetStreamCache(exchange.getIn());
90	                continue;
91	            }
92	
93	            // okay we found a filter then process it directly via its processor as we have already done the matching
94	            return filter.getProcessor().process(exchange, callback);
95	        }
96	
97	        if (otherwise != null) {
98	            // no filter matched then use otherwise
99	            notFiltered++;
100	            return otherwise.process(exchange, callback);
101	        } else {
102	            // when no filter matches and there is no otherwise, then just continue
103	            callback.done(true);
104	            return true;
105	        }
106	    }
107	
108	    @Override
109	    public String toString() {
110	        return id;
111	    }
112	
113	    @Override
114	    public String getTraceLabel() {
115	        return "choice";
116	    }
117	
118	    public List<FilterProcessor> getFilters() {
119	        return Arrays.asList(filters);
120	    }
121	
122	    public Processor getOtherwise() {
123	        return otherwise;
124	    }
125	
126	    /**
127	     * Gets the number of Exchanges that did not match any predicate and are routed using otherwise
128	     */
129	    public long getNotFilteredCount() {
130	        return notFiltered;
131	    }
132	
133	    /**
134	     * Reset counters.
135	     */
136	    public void reset() {
137	        for (int i = 0; i < len; i++) {
138	            filters[i].reset();
139	        }
140	        notFiltered = 0;
141	    }
142	
143	    @Override
144	    public List<Processor> next() {
145	        if (!hasNext()) {
146	            return null;
147	        }
148	        List<Processor> answer = new ArrayList<>();
149	        if (len > 0) {
150	            answer.addAll(Arrays.asList(filters));
151	        }
152	        if (otherwise != null) {
153	            answer.add(otherwise);
154	        }
155	        return answer;
156	    }
157	
158	    @Override
159	    public boolean hasNext() {
160	        return otherwise != null || len > 0;
161	    }
162	
163	    @Override
164	    public String getId() {
165	        return id;
166	    }
167	
168	    @Override
169	    public void setId(String id) {
170	        this.id = id;
171	    }
172	
173	    @Override
174	    public String getRouteId() {
175	        return routeId;
176	    }
177	
178	    @Override
179	    public void setRouteId(String routeId) {
180	        this.routeId = routeId;
181	    }
182	
183	    @Override
184	    public String getStepId() {
185	        return stepId;
186	    }
187	
188	    @Override
189	    public void setStepId(String stepId) {
190	        this.stepId = stepId;
191	    }
192	
193	    @Override
194	    protected void doInit() throws Exception {
195	        ServiceHelper.initService(Arrays.asList(filters), otherwise);
196	    }
197	
198	    @Override
199	    protected void doStart() throws Exception {
200	        ServiceHelper.startService(Arrays.asList(filters), otherwise);
201	    }
202	
203	    @Override
204	    protected void doStop() throws Exception {
205	        ServiceHelper.stopService(otherwise, Arrays.asList(filters));
206	    }
207	
208	    @Override
209	    protected void doShutdown() throws Exception {
210	        ServiceHelper.stopAndShutdownServices(otherwise, Arrays.asList(filters));
211	    }
212	
213	}
