36	import org.slf4j.LoggerFactory;
37	
38	public class ChoiceReifier extends ProcessorReifier<ChoiceDefinition> {
39	
40	    /**
41	     * The logger.
42	     */
43	    private static final Logger LOG = LoggerFactory.getLogger(ChoiceReifier.class);
44	
45	    public ChoiceReifier(Route route, ProcessorDefinition<?> definition) {
46	        super(route, ChoiceDefinition.class.cast(definition));
47	    }
48	
49	    @Override
50	    public Processor createProcessor() throws Exception {
51	        final boolean isPrecondition = Boolean.TRUE == parseBoolean(definition.getPrecondition());
52	        final List<FilterProcessor> filters = isPrecondition ? null : new ArrayList<>();
53	        for (WhenDefinition whenClause : definition.getWhenClauses()) {
54	            if (filters != null) {
55	                whenClause.preCreateProcessor();
56	                Predicate when = null;
57	                Processor output = null;
58	                if (!isDisabled(camelContext, whenClause)) {
59	                    // ensure id is assigned on when
60	                    whenClause.idOrCreate(camelContext.getCamelContextExtension().getContextPlugin(NodeIdFactory.class));
61	                    when = createPredicate(whenClause.getExpression());
62	                    output = createOutputsProcessor(whenClause.getOutputs());
63	                    if (output == null) {
64	                        // when with no outputs, then its like its disabled
65	                        // NOTE: resource closure is managed by Camel at a later stage.
66	                        output = new DisabledProcessor(); // NOSONAR
67	                    }
68	                }
69	                if (when != null) {
70	                    filters.add(new FilterProcessor(camelContext, when, output));
71	                }
72	            }
73	        }
74	        if (isPrecondition) {
75	            return getMatchingBranchProcessor();
76	        }
77	        Processor otherwiseProcessor = null;
78	        if (definition.getOtherwise() != null) {
79	            if (!isDisabled(camelContext, definition.getOtherwise())) {
80	                // ensure id is assigned on otherwise
81	                definition.getOtherwise()
82	                        .idOrCreate(camelContext.getCamelContextExtension().getContextPlugin(NodeIdFactory.class));
83	                otherwiseProcessor = createOutputsProcessor(definition.getOtherwise().getOutputs());
84	            }
85	        }
86	        ChoiceProcessor answer = new ChoiceProcessor(filters, otherwiseProcessor);
87	        answer.setDisabled(isDisabled(camelContext, definition));
88	        return answer;
89	    }
90	
91	    /**
92	     * @return the processor corresponding to the matching branch if any, {@code null} otherwise.
93	     */
94	    private Processor getMatchingBranchProcessor() throws Exception {
95	        // evaluate when predicates to optimize
96	        Exchange dummy = ExchangeHelper.getDummy(camelContext);
97	        for (WhenDefinition whenClause : definition.getWhenClauses()) {
98	            ExpressionDefinition exp = whenClause.getExpression();
99	            exp.initPredicate(camelContext);
100	
101	            Predicate predicate = exp.getPredicate();
102	            predicate.initPredicate(camelContext);
103	
104	            boolean matches = predicate.matches(dummy);
105	            if (matches) {
106	                LOG.debug("doSwitch selected: {}", whenClause.getLabel());
107	                return createOutputsProcessor(whenClause.getOutputs());
108	            }
109	        }
110	
111	        if (definition.getOtherwise() != null) {
112	            LOG.debug("doSwitch selected: otherwise");
113	            return createOutputsProcessor(definition.getOtherwise().getOutputs());
114	        }
115	
116	        // no cases were selected
117	        LOG.debug("doSwitch no when or otherwise selected");
118	        return null;
119	    }
120	
121	}
