31	import org.apache.camel.ExpressionFactory;
32	import org.apache.camel.NamedNode;
33	import org.apache.camel.Predicate;
34	import org.apache.camel.builder.ExpressionClause;
35	import org.apache.camel.model.language.ExpressionDefinition;
36	import org.apache.camel.spi.AsPredicate;
37	import org.apache.camel.spi.Metadata;
38	import org.apache.camel.spi.Resource;
39	
40	/**
41	 * Route messages based on a series of predicates
42	 */
43	@Metadata(label = "eip,routing")
44	@XmlRootElement(name = "choice")
45	@XmlType(propOrder = { "whenClauses", "otherwise" })
46	@XmlAccessorType(XmlAccessType.FIELD)
47	public class ChoiceDefinition extends NoOutputDefinition<ChoiceDefinition> {
48	
49	    @XmlElementRef(name = "when")
50	    @AsPredicate
51	    @Metadata(description = "Sets the when nodes")
52	    private List<WhenDefinition> whenClauses = new ArrayList<>();
53	    @XmlElement
54	    @Metadata(description = "Sets the otherwise node")
55	    private OtherwiseDefinition otherwise;
56	    @XmlAttribute
57	    @Metadata(label = "advanced", javaType = "java.lang.Boolean", defaultValue = "false")
58	    private String precondition;
59	
60	    public ChoiceDefinition() {
61	    }
62	
63	    protected ChoiceDefinition(ChoiceDefinition source) {
64	        super(source);
65	        this.whenClauses = ProcessorDefinitionHelper.deepCopyDefinitions(source.whenClauses);
66	        this.otherwise = source.otherwise != null ? source.otherwise.copyDefinition() : null;
67	        this.precondition = source.precondition;
68	    }
69	
70	    @Override
71	    public ChoiceDefinition copyDefinition() {
72	        return new ChoiceDefinition(this);
73	    }
74	
75	    @Override
76	    public String toString() {
77	        return "Choice[" + getWhenClauses() + (getOtherwise() != null ? " " + getOtherwise() : "") + "]";
78	    }
79	
80	    public String getPrecondition() {
81	        return precondition;
82	    }
83	
84	    /**
85	     * Indicates whether this Choice EIP is in precondition mode or not. If so its branches (when/otherwise) are
86	     * evaluated during startup to keep at runtime only the branch that matched.
87	     */
88	    public void setPrecondition(String precondition) {
