94	        if (otherwise != null) {
95	            output.setParent(this);
96	            otherwise.addOutput(output);
97	            prepareOutput(output);
98	        } else if (!whenClauses.isEmpty()) {
99	            output.setParent(this);
100	            WhenDefinition last = whenClauses.get(whenClauses.size() - 1);
101	            last.addOutput(output);
102	            prepareOutput(output);
103	        } else {
104	            super.addOutput(output);
105	        }
