120	    protected void prepareOutput(NamedNode output) {
121	        // grab camel context depends on if this is a regular route or a route configuration
122	        CamelContext context = this.getCamelContext();
123	        if (context == null) {
124	            RouteDefinition route = ProcessorDefinitionHelper.getRoute(this);
125	            if (route != null) {
126	                context = route.getCamelContext();
127	            } else {
128	                RouteConfigurationDefinition rc = this.getRouteConfiguration();
129	                if (rc != null) {
130	                    context = rc.getCamelContext();
131	                }
132	            }
133	        }
134	
135	        if (context != null && (context.isSourceLocationEnabled()
136	                || context.isDebugging() || context.isDebugStandby()
137	                || context.isTracing() || context.isTracingStandby())) {
138	            // we want to capture source location:line for every output (also when debugging or tracing enabled/standby)
139	            Resource resource = ProcessorDefinitionHelper.getResource(this);
140	            ProcessorDefinitionHelper.prepareSourceLocation(resource, output);
141	        }
