152	            otherwise.setDisabled(disabled);
153	        } else if (!whenClauses.isEmpty()) {
154	            WhenDefinition last = whenClauses.get(whenClauses.size() - 1);
155	            if (last.getOutputs().isEmpty()) {
156	                last.setDisabled(disabled);
157	            } else {
158	                super.disabled(disabled);
159	            }
160	        } else {
161	            super.disabled(disabled);
162	        }
163	        return this;
164	    }
