166	    // Fluent API
167	    // -------------------------------------------------------------------------
168	
169	    /**
170	     * Indicates that this Choice EIP is in precondition mode, its branches (when/otherwise) are then evaluated during
171	     * startup to keep at runtime only the branch that matched.
172	     *
173	     * @return the builder
174	     */
175	    public ChoiceDefinition precondition() {
