177	    }
178	
179	    /**
180	     * Indicates whether this Choice EIP is in precondition mode or not. If so its branches (when/otherwise) are
181	     * evaluated during startup to keep at runtime only the branch that matched.
182	     *
183	     * @param  precondition the flag indicating if it is in precondition mode or not.
184	     * @return              the builder
185	     */
186	    public ChoiceDefinition precondition(boolean precondition) {
187	        setPrecondition(Boolean.toString(precondition));
188	        return this;
189	    }
