191	    /**
192	     * Sets the predicate for the when node
193	     *
194	     * @param  predicate the predicate
195	     * @return           the builder
196	     */
197	    public ChoiceDefinition when(@AsPredicate Predicate predicate) {
198	        addClause(new WhenDefinition(predicate));
199	        return this;
200	    }
201	
202	    /**
203	     * Creates an expression for the when node
204	     *
205	     * @return expression to be used as builder to configure the when node
206	     */
207	    @AsPredicate
208	    public ExpressionClause<ChoiceDefinition> when() {
209	        ExpressionClause<ChoiceDefinition> clause = new ExpressionClause<>(this);
210	        addClause(new WhenDefinition((Predicate) clause));
211	        return clause;
212	    }
