214	    /**
215	     * Sets the otherwise node
216	     *
217	     * @return the builder
218	     */
219	    public ChoiceDefinition otherwise() {
220	        if (this.otherwise != null) {
221	            throw new IllegalArgumentException(
222	                    "Cannot add a 2nd otherwise to this choice: " + this
223	                                               + ". If you have nested choice then you may need to end().endChoice() to go back to parent choice.");
224	        }
225	        OtherwiseDefinition answer = new OtherwiseDefinition();
226	        addClause(answer);
227	        return this;
228	    }
229	
