277	    @Override
278	    public WhenDefinition findMatchingWhen(String id) {
279	        for (WhenDefinition when : whenClauses) {
280	            for (ProcessorDefinition<?> out : when.getOutputs()) {
281	                if (out.getId().equals(id)) {
