342	    @Override
343	    public void preCreateProcessor() {
344	        if (whenClauses == null || whenClauses.isEmpty()) {
345	            return;
346	        }
347	        for (WhenDefinition when : whenClauses) {
348	            ExpressionDefinition exp = when.getExpression();
349	            if (exp.getExpressionType() != null) {
