17	package org.apache.camel.processor;
18	
19	import org.apache.camel.AsyncCallback;
20	import org.apache.camel.CamelContext;
21	import org.apache.camel.Exchange;
22	import org.apache.camel.Predicate;
23	import org.apache.camel.Processor;
24	import org.apache.camel.Traceable;
25	import org.apache.camel.spi.IdAware;
26	import org.apache.camel.spi.RouteIdAware;
27	import org.apache.camel.spi.StepIdAware;
28	import org.apache.camel.support.service.ServiceHelper;
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	
32	/**
33	 * The processor which implements the <a href="http://camel.apache.org/message-filter.html">Message Filter</a> EIP
34	 * pattern.
35	 */
36	public class FilterProcessor extends BaseDelegateProcessorSupport implements Traceable, IdAware, RouteIdAware, StepIdAware {
37	
38	    private static final Logger LOG = LoggerFactory.getLogger(FilterProcessor.class);
39	
40	    private final CamelContext context;
41	    private String id;
42	    private String routeId;
43	    private String stepId;
44	    private final Predicate predicate;
45	    private transient long filtered;
46	    private String statusPropertyName;
47	
48	    public FilterProcessor(CamelContext context, Predicate predicate, Processor processor) {
49	        super(processor);
50	        this.context = context;
51	        this.predicate = predicate;
52	    }
53	
54	    public String getStatusPropertyName() {
55	        return statusPropertyName;
56	    }
57	
58	    public void setStatusPropertyName(String statusPropertyName) {
59	        this.statusPropertyName = statusPropertyName;
60	    }
61	
62	    @Override
63	    protected void doInit() throws Exception {
64	        super.doInit();
65	        predicate.init(context);
66	    }
67	
68	    @Override
69	    public boolean process(Exchange exchange, AsyncCallback callback) {
70	        boolean matches = false;
71	
72	        try {
73	            matches = matches(exchange);
74	            if (statusPropertyName != null) {
75	                exchange.setProperty(statusPropertyName, matches);
76	            }
77	        } catch (Exception e) {
78	            exchange.setException(e);
79	        }
80	
81	        if (matches) {
82	            return processor.process(exchange, callback);
83	        } else {
84	            callback.done(true);
85	            return true;
86	        }
87	    }
88	
89	    public boolean matches(Exchange exchange) {
90	        boolean matches = predicate.matches(exchange);
91	
92	        LOG.debug("Filter matches: {} for exchange: {}", matches, exchange);
93	
94	        if (matches) {
95	            filtered++;
96	        }
97	
98	        return matches;
99	    }
100	
101	    @Override
102	    public String toString() {
103	        return id;
104	    }
105	
106	    @Override
107	    public String getId() {
108	        return id;
109	    }
110	
111	    @Override
112	    public void setId(String id) {
113	        this.id = id;
114	    }
115	
116	    @Override
117	    public String getRouteId() {
118	        return routeId;
119	    }
120	
121	    @Override
122	    public void setRouteId(String routeId) {
123	        this.routeId = routeId;
124	    }
125	
126	    @Override
127	    public String getStepId() {
128	        return stepId;
129	    }
130	
131	    @Override
132	    public void setStepId(String stepId) {
133	        this.stepId = stepId;
134	    }
135	
136	    @Override
137	    public String getTraceLabel() {
138	        return "filter[if: " + predicate + "]";
139	    }
140	
141	    public Predicate getPredicate() {
142	        return predicate;
143	    }
144	
145	    /**
146	     * Gets the number of Exchanges that matched the filter predicate and therefore as filtered.
147	     */
148	    public long getFilteredCount() {
149	        return filtered;
150	    }
151	
152	    /**
153	     * Reset counters.
154	     */
155	    public void reset() {
156	        filtered = 0;
157	    }
158	
159	    @Override
160	    protected void doStart() throws Exception {
161	        super.doStart();
162	        // restart counter
163	        reset();
164	        ServiceHelper.startService(predicate);
165	    }
166	
167	    @Override
168	    protected void doStop() throws Exception {
169	        ServiceHelper.stopService(predicate);
170	        super.doStop();
171	    }
172	}
